const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let n;
let s;

rl.on('line', (line) => {
    if (n === undefined) {
        n = parseInt(line);
    } else {
        s = line.trim();
        rl.close();
    }
});

rl.on('close', () => {
    let count = 0;
    for (let i = 0; i < n; i++) {
        let x = 0, y = 0;
        for (let j = i; j < n; j++) {
            const c = s[j];
            if (c === 'U') y++;
            else if (c === 'D') y--;
            else if (c === 'R') x++;
            else if (c === 'L') x--;
            if (x === 0 && y === 0) {
                count++;
            }
        }
    }
    console.log(count);
});
