    const dx = { U: 0, D: 0, L: -1, R: 1 };
    const dy = { U: 1, D: -1, L: 0, R: 0 };
    let x = 0, y = 0;
    const map = new Map();
    map.set('0,0', 1);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const c = s[i];
        x += dx[c];
        y += dy[c];
        const key = `${x},${y}`;
        ans += (map.get(key) || 0);
        map.set(key, (map.get(key) || 0) + 1);
    }
    console.log(ans);
});
